<style>
.hnt-ai-page{display:grid;gap:22px;color:#fff}.hnt-ai-hero,.hnt-ai-section,.hnt-ai-metrics>div{background:var(--acp-panel,#1e1f25);border:1px solid var(--acp-border,#282c38);border-radius:20px}.hnt-ai-hero{padding:26px;display:flex;justify-content:space-between;gap:20px;align-items:center}.hnt-ai-hero h1{font-size:28px;margin:5px 0 9px;font-weight:600}.hnt-ai-hero p{max-width:760px;margin:0;color:var(--acp-muted,#9ba0af);line-height:1.5}.hnt-ai-kicker{color:var(--acp-blue,#246cf9);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}.hnt-ai-hero-badge{border:1px solid var(--acp-border-2,#3c4254);border-radius:999px;padding:8px 12px;white-space:nowrap;color:#d6d9e3}.hnt-ai-notice{margin:0;padding:13px 17px;background:#352a21;border:1px solid #765431;border-radius:12px;color:#ffcf8b}.hnt-ai-notice p{margin:0}.hnt-ai-success{background:#1b352f;border-color:#337c66;color:#9aebcc}.hnt-ai-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.hnt-ai-metrics>div{padding:18px;display:flex;flex-direction:column;gap:5px}.hnt-ai-metrics strong{font-size:23px;font-weight:600}.hnt-ai-metrics span,.hnt-ai-meta,.hnt-ai-muted{color:var(--acp-muted,#9ba0af);font-size:12px}.hnt-ai-section{padding:22px}.hnt-ai-section-head{margin-bottom:18px}.hnt-ai-section-head h2{margin:0 0 5px;font-size:19px;font-weight:600}.hnt-ai-section-head p{margin:0;color:var(--acp-muted,#9ba0af);line-height:1.5}.hnt-ai-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:14px}.hnt-ai-card,.hnt-ai-draft{min-width:0;background:var(--acp-active,#282c38);border:1px solid var(--acp-border-2,#3c4254);border-radius:14px;padding:17px}.hnt-ai-card-head,.hnt-ai-draft-top{display:flex;justify-content:space-between;align-items:start;gap:10px}.hnt-ai-card h3,.hnt-ai-draft h3{margin:0 0 8px;font-size:16px;font-weight:600}.hnt-ai-pill{display:inline-block;padding:4px 8px;border-radius:999px;background:#373c49;color:#b7bdcb;font-size:11px}.hnt-ai-pill.hnt-ai-on{color:#88e7c0;background:#184a3d}.hnt-ai-link{font-size:12px;color:#89adff!important;text-decoration:underline!important;white-space:nowrap}.hnt-ai-meta{line-height:1.5}.hnt-ai-details{border-top:1px solid var(--acp-border-2,#3c4254);padding-top:11px;margin-top:14px}.hnt-ai-details summary,.hnt-ai-preview summary{cursor:pointer;color:#dbe5ff;font-size:13px}.hnt-ai-details form{display:grid;gap:10px;margin-top:12px}.hnt-ai-details label,.hnt-ai-edit label{display:grid;gap:5px;font-size:12px;color:#c4c8d3}.hnt-ai-page textarea{width:100%;resize:vertical;border:1px solid var(--acp-border-2,#3c4254);border-radius:9px;padding:10px;background:var(--acp-panel,#1e1f25);color:#fff;line-height:1.4}.hnt-ai-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:13px}.hnt-ai-button{border:1px solid #3977f7;border-radius:8px;background:var(--acp-blue,#246cf9);color:#fff;padding:8px 11px;cursor:pointer;font-size:12px;font-weight:600}.hnt-ai-button:hover{filter:brightness(1.12)}.hnt-ai-button:disabled{opacity:.45;cursor:not-allowed}.hnt-ai-secondary{background:transparent;border-color:var(--acp-border-2,#3c4254);color:#d2d6e0}.hnt-ai-provision p{color:var(--acp-muted,#9ba0af);font-size:12px}.hnt-ai-preview pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:420px;overflow:auto;background:#141518;border-radius:10px;padding:15px;font-size:12px;line-height:1.5}.hnt-ai-preview details{margin-top:8px}.hnt-ai-drafts{display:grid;gap:12px}.hnt-ai-draft{display:grid;gap:9px}.hnt-ai-draft .hnt-ai-meta,.hnt-ai-draft .hnt-ai-body{margin:0}.hnt-ai-body{line-height:1.5;white-space:pre-wrap}.hnt-ai-edit{display:grid;justify-items:start;gap:9px}.hnt-ai-edit textarea{min-width:min(600px,100%)}.hnt-ai-draft .hnt-ai-actions{margin:0}.hnt-ai-publish{background:#197456;border-color:#197456}@media(max-width:900px){.hnt-ai-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:580px){.hnt-ai-hero{display:block;padding:20px}.hnt-ai-hero-badge{display:inline-block;margin-top:15px}.hnt-ai-section{padding:16px}.hnt-ai-metrics{gap:8px}.hnt-ai-metrics>div{padding:13px}.hnt-ai-metrics strong{font-size:19px}.hnt-ai-grid{grid-template-columns:minmax(0,1fr)}}
</style>
